<?php

namespace App\Providers;

use Illuminate\Support\ServiceProvider;
use Illuminate\Support\Facades\Event;
use Illuminate\Mail\Events\MessageSent;
use App\Services\SentItemLog;

class AppServiceProvider extends ServiceProvider
{
    /**
     * Register any application services.
     */
    public function register(): void
    {
        //
    }

    /**
     * Bootstrap any application services.
     */
    public function boot(): void
    {
        // Centrally record successfully handed-off Laravel emails, including
        // mail generated by scheduled tasks and Mailable classes.
        Event::listen(MessageSent::class, static function (MessageSent $event): void {
            // Log/array mailers do not actually hand email to a delivery provider.
            if (in_array(config('mail.default'), ['log', 'array'], true)) return;
            if (! $event->sent) return;
            $message = $event->sent->getOriginalMessage();
            if (! $message instanceof \Symfony\Component\Mime\Email) return;

            $sender = $message->getFrom();
            $senderAddress = $sender !== [] ? $sender[0]->getAddress() : null;
            $subject = $message->getSubject();
            $log = app(SentItemLog::class);
            $source = $log->sourceFromStack();
            if ($source === 'LVS') $source = 'LVS e-mail';
            $recipients = [
                'to' => $message->getTo(),
                'cc' => $message->getCc(),
                'bcc' => $message->getBcc(),
            ];
            foreach ($recipients as $type => $addresses) {
                foreach ($addresses as $address) {
                    $log->record('email', $address->getAddress(), $senderAddress,
                        $subject, 'sent', $source, null, null, $type);
                }
            }
        });
    }
}
